"""Cut existing ElevenLabs masters at measured silence gaps; no provider calls."""
from pathlib import Path
import hashlib, json, re, subprocess, wave
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'assets/production/needle-quay/reward-voices'
OUT=BASE/'clips'; OUT.mkdir(exist_ok=True)
companion_keys=['title','badge','roamer','companion']
street_keys=['title_friend','title_favorite','title_icon','badge_chase','badge_lantern','badge_dock','badge_repair','badge_record','badge_signal','badge_echo','badge_pulse','badge_finale','roamer','companion']
records=[]; catalog={}
for record in json.loads((BASE/'source-manifest.json').read_text()):
    path=BASE/'source'/record['source']
    records.append(dict(record,kind='original',sha256=hashlib.sha256(path.read_bytes()).hexdigest()))
for run in json.loads((BASE/'word-timings.json').read_text()):
    source=BASE/'source'/run['source']
    duration=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','default=noprint_wrappers=1:nokey=1',str(source)],text=True))
    result=subprocess.run(['ffmpeg','-hide_banner','-i',str(source),'-af','silencedetect=noise=-38dB:d=0.55','-f','null','-'],capture_output=True,text=True,check=True)
    starts=[float(x) for x in re.findall(r'silence_start: ([0-9.]+)',result.stderr)]
    ends=[float(x) for x in re.findall(r'silence_end: ([0-9.]+)',result.stderr)]
    gaps=[(a,b) for a,b in zip(starts,ends) if a>0.2 and b<duration-0.2]
    if len(gaps)!=len(run['lines'])-1: raise ValueError(f"Review silence boundaries for {source}: {gaps}")
    clean=re.sub(r'\[[^]]*\]','',run['text'])
    normalize=lambda s: re.sub(r'[^a-z0-9]','',s.lower())
    if normalize(clean)!=normalize(' '.join(run['lines'])): raise ValueError('Transcript differs from intended cues')
    keys=street_keys if run['speaker'].startswith('street_') else companion_keys
    for i,(key,words) in enumerate(zip(keys,run['lines'])):
        start=max(0,gaps[i-1][1]-0.08) if i else 0
        end=min(duration,gaps[i][0]+0.12) if i<len(gaps) else duration
        cue=run['speaker']+'_'+key
        target=OUT/(cue+'.wav')
        subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-ss',str(start),'-i',str(source),'-t',str(end-start),'-af','loudnorm=I=-19:TP=-2:LRA=7,afade=t=in:d=0.005','-ac','1','-ar','44100','-c:a','pcm_s16le',str(target)],check=True)
        with wave.open(str(target)) as wav: seconds=wav.getnframes()/wav.getframerate()
        catalog[cue]={'file':target.name,'text':words,'duration':round(seconds,4)}
        records.append({'kind':'runtime-clip','file':target.relative_to(ROOT).as_posix(),'source':source.relative_to(ROOT).as_posix(),'generationId':run['sourceGenerationId'],'transcriptGenerationId':run['transcriptGenerationId'],'start':start,'end':end,'text':words,'duration':seconds,'sha256':hashlib.sha256(target.read_bytes()).hexdigest()})
(ROOT/'src/shared/QuayRewardVoiceClips.luau').write_text('-- Generated by tools/prepare_reward_voice_clips.py; local Studio audio only.\nreturn game:GetService("HttpService"):JSONDecode([=['+json.dumps(catalog,separators=(',',':'))+']=])\n')
(BASE/'provenance.json').write_text(json.dumps({'provider':'ElevenLabs','model':'eleven_v4','selection':'Fourth take per speaker, matching the source selected for word timings. All 16 originals retained.','processing':'Silence gaps longer than 0.55s at -38dB; 80ms lead and 120ms tail; mono PCM16 44.1kHz, loudnorm I=-19 TP=-2.','records':records,'runtimeVerified':False,'robloxUploads':0},indent=2))
print('Prepared',len(catalog),'voice clips; duration range',round(min(x['duration'] for x in catalog.values()),2),'-',round(max(x['duration'] for x in catalog.values()),2),'seconds')
